(function(){"use strict";let r={},l=[],g=!1;self.onmessage=p=>{const o=p.data;if(o.type==="init"){r=o.gridToArea,l=o.flows,g=!0,self.postMessage({type:"ready"});return}if(!g){self.postMessage({type:"error",id:o.id,error:"Worker not initialized"});return}if(o.type==="analyze_self_containment"){const e={},f=new Set(Object.values(r));for(const t of f)e[t]={internal:0,outgoing:0,incoming:0};for(const t of l){const i=r[t.origin],a=r[t.dest];!i||!a||(i===a?e[i].internal+=t.count:(e[i]&&(e[i].outgoing+=t.count),e[a]&&(e[a].incoming+=t.count)))}self.postMessage({type:"result",id:o.id,result:e});return}if(o.type==="get_inter_area_flows"){const{areaCode:e,targetArea:f}=o,t=new Set;for(const[n,s]of Object.entries(r))s===e&&t.add(n);let i=0,a=0,y=0;const u={},d={};for(const n of l){const s=r[n.origin],c=r[n.dest];if(s===e&&c===e)i+=n.count;else if(s===e){if(f&&c!==f)continue;a+=n.count,c&&(u[c]=(u[c]||0)+n.count)}else if(c===e){if(f&&s!==f)continue;y+=n.count,s&&(d[s]=(d[s]||0)+n.count)}}self.postMessage({type:"result",id:o.id,result:{areaCode:e,gridCount:t.size,internal:i,outgoing:a,incoming:y,outByArea:u,inByArea:d}});return}}})();
